---RefreshTaskByTaskId 根据任务id刷新任务信息
---@param taskId integer @ 任务id
function ChallengeTaskCellItem:RefreshTaskByTaskId(taskId)
    -- 刷新任务描述文字
    local taskDescr = GCQUtils.GetChallengeTaskDescr(taskId)
    self.DescrLabel.text = taskDescr

    -- 刷新任务奖励
    ---@type GachaCoinQuestTaskVo
    local taskConfig = GCQUtils.GetVoById(AutoIds.IdSetting704, taskId)
    local rewardsInfo = parse_rewards(taskConfig.reward, taskConfig.rewardNum, ';')
    self:RefreshTaskRewards(rewardsInfo)
end

---RefreshTaskByTaskState 根据任务状态刷新任务信息
---@param taskState GachaCoinQuestConstants.Defines.TaskState 任务状态
function ChallengeTaskCellItem:RefreshTaskByTaskState(taskState)
    local uiConfig = UIConfig[taskState or GCQConstants.Defines.TaskState.Default]
    -- 刷新底图
    self.Bg:LoadSprite(uiConfig.BgPath)

    -- 刷新文字版式
    self.DescrLabel.fontSize = uiConfig.DescrFontSize
    self.DescrLabel.color = uiConfig.DescrFontColor

    -- 领取文字
    KTool.SetActive(self.DrawHint.gameObject, GCQConstants.Defines.TaskState.CanDrawRewards == taskState)

    -- 完成icon
    KTool.SetActive(self.CompleteIcon.gameObject, GCQConstants.Defines.TaskState.Complete == taskState)
    KTool.SetActive(self.Cover.gameObject, GCQConstants.Defines.TaskState.Complete == taskState)

    -- 刷新道具图标位置
    local pivot = Vector2.New(0.5, 0.5)
    local padding = 10
    ---@type UnityEngine.RectTransform
    local rectTransfrom = nil
    local fixedSize = nil
    local amount = #self.rewardsInfo
    ---@type UnityEngine.GameObject
    local goodsNode = nil
    for index = 1, amount do
        goodsNode = self.rewardsIcon[index]
        -- 位置
        rectTransfrom = goodsNode:GetComponent(RectTransform_)
        rectTransfrom.pivot = pivot
        fixedSize = rectTransfrom.sizeDelta * GoodsNodeScale
        rectTransfrom.anchoredPosition = Vector2.New(
            0 + (index - 0.5 - amount / 2) * (fixedSize.x + padding),
            GCQConstants.Defines.TaskState.CanDrawRewards == taskState and 0 or -10
        )
    end
end

---刷新道具奖励
---@param rewardsInfo table[] 奖励信息
function ChallengeTaskCellItem:RefreshTaskRewards(rewardsInfo)
    self.rewardsInfo = rewardsInfo
    -- 隐藏老的道具节点
    for _, rewardsNode in ipairs(self.rewardsIcon) do
        KTool.SetActive(rewardsNode, false)
    end

    local goodsId = nil
    local goodsAmount = nil
    local rewardsAmount = #rewardsInfo
    for index, rewardsInfo_ in ipairs(rewardsInfo) do

        goodsId = checkInt(rewardsInfo_.goodsId)
        goodsAmount = checkInt(rewardsInfo_.goodsNum)

        local go = self.rewardsIcon[index]
        if IsNull(go) then
            ---@type Engine.Modules.AbstractResourceLoader
            -- local loader
            -- 为空 创建一个道具node
            go = GameUtils.LoadBundleSync("Prefabs/Common/GoodNode.prefab", self.RewardsInfo.gameObject)
            self.rewardsIcon[index] = go
            -- self.rewardsIconLoader[index] = loader
        else
            KTool.SetActive(go, true)
        end

        -- 刷新道具节点
        if not IsNull(go) then
            local goodsScript = GetLuaBehaviour(go, "Game.Behaviours.GoodNodeMB")
            if not IsNull(goodsScript) and not IsNull(goodsScript.Env) then
                goodsScript.Env:Reload({
                    goodsId = goodsId,
                    isShowNo = true,
                    text = tostring(goodsAmount)
                })
                goodsScript.Env:SetClickCallback(function()
                    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(rewardsInfo_.goodsId)
                    if isTable(vo) then
                        GameUtils.ShowCommonTipsBoard(go, vo.name, vo.desc, vo.quality, vo.id)
                    end
                end)
            end
        end

        -- 缩放
        local reverseScale = go:GetComponent(ReverseScale_)
        reverseScale.scale = GoodsNodeScale
        reverseScale:ResetScale()
        --reverseScale.scale = GoodsNodeScale

    end
end

