---TaskDrawRewards 挑战任务领取奖励
function ChallengeTaskCellItem:TaskDrawRewards()
    local questId = self:GetQuestId()
    local taskId = self:GetTaskId()

    GameUtils.Request(
        Interfaces.GachaCoinQuestChallengeTaskDraw, {copyId = questId, taskId = taskId},
        function (request, response)
            if 0 == checkInt(response.errCode) then
                self:TaskDrawRewardsCallback(response.data)
            end
        end
    )

    -- debug --
    -- self:TaskDrawRewardsCallback({})
    -- debug --
end

---TaskDrawRewardsCallback 领取奖励回调
---@param responseData table 服务器返回
function ChallengeTaskCellItem:TaskDrawRewardsCallback(responseData)
    local questId = self:GetQuestId()
    local taskId = self:GetTaskId()
    local taskState = GCQConstants.Defines.TaskState.Complete

    local rewards = responseData.rewards or {}
    --奖励入包
    GoodsUtils.DrawRewards(rewards)
    -- 领取奖励
    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })

    -- 刷新数据
    local taskState = GCQConstants.Defines.TaskState.Complete
    ---@type GachaCoinQuestComponent
    local gachaCoinQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.GachaCoinQuestComponent)
    gachaCoinQuestComponent:DrawChallengeTaskRewards(questId, taskId, taskState)
    self:SetTaskState(taskState)

    -- 刷新界面
    self:RefreshTaskByTaskState(taskState)
end


