---SetCellClickHandler 设置格子的点击回调
function ChallengeTaskCellItem:TaskCellClickHandler()
    if GCQConstants.Defines.TaskState.Complete == self.taskState then
        GameUtils.Toast(localize('奖励已领取'))
    elseif GCQConstants.Defines.TaskState.Default == self.taskState then
        GameUtils.Toast(localize('任务尚未完成'))
    elseif GCQConstants.Defines.TaskState.CanDrawRewards == self.taskState then
        self:TaskDrawRewards()
    else
        GameUtils.Toast(localize('数据错误'))
    end

    -- debug --
    -- self:TaskDrawRewards()
    -- debug --
end


